// Content is the typed content of one WhatsApp message: the discriminator
// Type plus exactly the one member it names (message-model §3.1). It is the
// wire type (agent events and SendMessage), the stored JSON (service ledger
// and send jobs) and the API type. Context is shared by every type.
//
// Decoding is lenient: an unknown type or a missing or extra member decodes
// without error and fails Content.Validate. Every boundary (agent before
// publish, service ingress, service read, POST /v1/messages) validates, and a
// received or stored value that fails is replaced by InvalidContent, so it
// never reaches a client half-formed.
//
// The shape is a tagged-sibling union for apigen (OpenAPI oneOf with a "type"
// discriminator); register it with genspec.ContentUnion.
type Content struct {
	Type             ContentType              `json:"type"`
	Text             *ContentText             `json:"text,omitzero"`
	Image            *ContentImage            `json:"image,omitzero"`
	Video            *ContentVideo            `json:"video,omitzero"`
	Audio            *ContentAudio            `json:"audio,omitzero"`
	Document         *ContentDocument         `json:"document,omitzero"`
	Sticker          *ContentSticker          `json:"sticker,omitzero"`
	Location         *ContentLocation         `json:"location,omitzero"`
	Contacts         *ContentContacts         `json:"contacts,omitzero"`
	Poll             *ContentPoll             `json:"poll,omitzero"`
	PollVote         *ContentPollVote         `json:"poll_vote,omitzero"`
	Interactive      *ContentInteractive      `json:"interactive,omitzero"`
	InteractiveReply *ContentInteractiveReply `json:"interactive_reply,omitzero"`
	System           *ContentSystem           `json:"system,omitzero"`
	Call             *ContentCall             `json:"call,omitzero"`
	Unavailable      *ContentUnavailable      `json:"unavailable,omitzero"`
	Unsupported      *ContentUnsupported      `json:"unsupported,omitzero"`
	Context          *ContentContext          `json:"context,omitzero"`
}

// ContentType is the discriminator of Content. Each value is also the JSON
// name of the one member that carries the content.
type ContentType string

const (
	ContentTypeText             ContentType = "text"
	ContentTypeImage            ContentType = "image"
	ContentTypeVideo            ContentType = "video"
	ContentTypeAudio            ContentType = "audio"
	ContentTypeDocument         ContentType = "document"
	ContentTypeSticker          ContentType = "sticker"
	ContentTypeLocation         ContentType = "location"
	ContentTypeContacts         ContentType = "contacts"
	ContentTypePoll             ContentType = "poll"
	ContentTypePollVote         ContentType = "poll_vote"
	ContentTypeInteractive      ContentType = "interactive"
	ContentTypeInteractiveReply ContentType = "interactive_reply"
	ContentTypeSystem           ContentType = "system"
	ContentTypeCall             ContentType = "call"
	ContentTypeUnavailable      ContentType = "unavailable"
	ContentTypeUnsupported      ContentType = "unsupported"
)

// Values returns the valid ContentType values.
func (ContentType) Values() []string {
	return []string{
		string(ContentTypeText),
		string(ContentTypeImage),
		string(ContentTypeVideo),
		string(ContentTypeAudio),
		string(ContentTypeDocument),
		string(ContentTypeSticker),
		string(ContentTypeLocation),
		string(ContentTypeContacts),
		string(ContentTypePoll),
		string(ContentTypePollVote),
		string(ContentTypeInteractive),
		string(ContentTypeInteractiveReply),
		string(ContentTypeSystem),
		string(ContentTypeCall),
		string(ContentTypeUnavailable),
		string(ContentTypeUnsupported),
	}
}

// Validate reports whether e is a defined ContentType value.
func (e ContentType) Validate() error {
	switch e {
	case ContentTypeText, ContentTypeImage, ContentTypeVideo, ContentTypeAudio, ContentTypeDocument, ContentTypeSticker, ContentTypeLocation, ContentTypeContacts, ContentTypePoll, ContentTypePollVote, ContentTypeInteractive, ContentTypeInteractiveReply, ContentTypeSystem, ContentTypeCall, ContentTypeUnavailable, ContentTypeUnsupported:
		return nil
	default:
		return errors.New("invalid ContentType: " + string(e))
	}
}

