// list, template button or interactive response): the selected ID and the
// text the user saw. The answered message is Context.Quoted.
type ContentInteractiveReply struct {
	SelectedID string `json:"selected_id,omitzero"`
	Text       string `json:"text,omitzero"`
}

// ContentSystem records a chat event that is not a user message. The actor
// is the message key's sender, which is empty when WhatsApp did not report
// one. The agent synthesizes the key's WID of a system event that is not a
// message ("SYS" + hex digest of its type, chat, time and change). Fields
// outside the event's own rule are empty:
//
//   - ephemeral_changed: EphemeralSeconds (zero turns the timer off);
//   - group_name_changed: Name; group_topic_changed: Topic (empty removes it);
//   - group_participants_*: Participants (at least one);
//   - group_announce_changed, group_locked_changed: Enabled.
type ContentSystem struct {
	Event            SystemEvent `json:"event"`
	EphemeralSeconds *uint32     `json:"ephemeral_seconds,omitzero"`
	Name             string      `json:"name,omitzero"`
	Topic            string      `json:"topic,omitzero"`
	Participants     []Party     `json:"participants,omitzero"`
	Enabled          *bool       `json:"enabled,omitzero"`
}

// SystemEvent is the kind of a ContentSystem record.
type SystemEvent string

// ContentCall records an unanswered incoming call (CallOffer).
type ContentCall struct {
	CallID string `json:"call_id"`
	Video  bool   `json:"video,omitzero"`
}

// ContentUnavailable stands in for a message whose content exists but is not
// recorded. ExpectedType is the type detected, when known (for example image
// for a view-once photo). Target is set for a poll vote that could not be
// decrypted.
type ContentUnavailable struct {
	Reason       UnavailableReason `json:"reason"`
	ExpectedType ContentType       `json:"expected_type,omitzero"`
	Target       *MessageKey       `json:"target,omitzero"`
}

// UnavailableReason is why a ContentUnavailable message has no content.
type UnavailableReason string

// ContentUnsupported records a message the model does not represent.
// ProtoField and FieldNumber name the waE2E.Message field that was set; both
// are empty when no known field was set. No raw proto is kept, so support for
// a new format applies from the release that adds it (message-model §3.3).
type ContentUnsupported struct {
	ProtoField  string            `json:"proto_field,omitzero"`
	FieldNumber int32             `json:"field_number,omitzero"`
	Reason      UnsupportedReason `json:"reason"`
}

// UnsupportedReason is why a message is recorded as ContentUnsupported.
type UnsupportedReason string

// ContentContext is the context shared by every content type: the quoted
