type Message struct {
	Template       *MessageTemplateReference `json:"template,omitzero"`
	ID             string                    `json:"id"`
	AgentID        string                    `json:"agent_id"`
	OrganizationID string                    `json:"organization_id,omitzero"`
	From           string                    `json:"from,omitzero"` // The agent's current phone number, which may differ from its number when the message was sent.
	// The recipient phone; absent for an operation in a chat whose
	// counterpart has no known phone.
	To        string                `json:"to,omitzero"`
	Type      MessageKind           `json:"type"`
	Text      *MessageText          `json:"text,omitzero"`        // The body of a text send, or the new body of an edit.
	ReplyToID *string               `json:"reply_to_id,omitzero"` // The chat message a reply quotes.
	TargetID  *string               `json:"target_id,omitzero"`   // The chat message a reaction, edit or revoke changes.
	Reaction  *MessageReactionEmoji `json:"reaction,omitzero"`
	Redacted  bool                  `json:"redacted,omitzero"` // Whether the message text is withheld from this response.
	// Message sending status; delivered does not confirm receipt by the recipient.
	// expired means the service stopped scheduling the message at not_after
	// before it could confirm a send. It is not proof the message was not sent:
	// a send already started can still report and turn it delivered, so do not
	// treat expired as safe to resend.
	Status         MessageStatus     `json:"status"`
	SendWindow     *SendWindow       `json:"send_window,omitzero"` // The window the message was accepted with; it is sent only while open.
	NotBefore      *time.Time        `json:"not_before,omitzero"`  // The message is not sent before this time.
	NotAfter       *time.Time        `json:"not_after,omitzero"`   // The service stops trying to send the message after this time.
	Priority       SendPriorityClass `json:"priority,omitzero"`    // Send priority class and offset the message was accepted with.
	PriorityOffset int8              `json:"priority_offset"`
	Error          *MessageError     `json:"error,omitzero"`
	CreateAt       time.Time         `json:"create_at"`
	UpdateAt       time.Time         `json:"update_at"`
	// When the message was sent to WhatsApp (single tick); it does not
	// confirm receipt by the recipient: see receipt.
	DeliveredAt time.Time       `json:"delivered_at,omitzero"`
	Receipt     *MessageReceipt `json:"receipt,omitzero"`      // WhatsApp receipt state, read-only; set on GET responses.
	BroadcastID *string         `json:"broadcast_id,omitzero"` // The broadcast the message was sent for.
}

