type CreateMessageInput struct {
	// The agent to send from. Required for organization-scoped requests
	// unless reply_to_id or an operation names a chat message, whose agent
	// it then must be. Authorized requests without an organization may omit
	// it to select an available sender.
	AgentID string `json:"agent_id,omitzero"`
	// The recipient. Required unless reply_to_id or an operation (reaction,
	// edit, revoke) names a chat message: the send then goes to that
	// message's chat, and to, if given, must be that chat's phone.
	To       string               `json:"to,omitzero"`
	Type     CreateMessageType    `json:"type"`
	Text     *MessageText         `json:"text,omitzero"`
	Template *SendMessageTemplate `json:"template,omitzero"` // Template sends render server-side; replies may use them too.
	// Reaction, edit and revoke change an earlier message in a direct
	// chat. Edit and revoke apply to the agent's own messages and require
	// whatsapp.message.write.
	Reaction *MessageReaction `json:"reaction,omitzero"`
	Edit     *MessageEdit     `json:"edit,omitzero"`
	Revoke   *MessageRevoke   `json:"revoke,omitzero"`
	// Makes a text or template send a reply quoting that chat message (a
	// direct chat only); quoting a received message also requires
	// whatsapp.inbound.read.
	ReplyToID string `json:"reply_to_id,omitzero"`
	// How the recipient phone is resolved; not allowed with reply_to_id or
	// an operation, which send to the message's chat.
	Strategy SendMessageStrategy `json:"strategy,omitzero"`
	// Send priority class. Defaults to normal (critical for platform service callers).
	// Organization callers may request up to interaction; critical is refused with 403.
	// Priority orders an agent's queue only; it never changes pacing.
	Priority       SendPriorityClass `json:"priority,omitzero"`
	PriorityOffset int8              `json:"priority_offset,omitzero"` // Orders messages within the class; higher is sent first.
	// A recurring local window in which the message may be sent; outside it
	// the message waits for the next opening. Not supported by local
	// generation-0 agents (409).
	SendWindow *SendWindow `json:"send_window,omitzero"`
	NotBefore  *time.Time  `json:"not_before,omitzero"` // Scheduled send: the message is not sent before this time.
	// After this time the service stops trying to send the message and it
	// ends expired. Must be in the future, after not_before, and after the
	// window's first opening.
	NotAfter *time.Time `json:"not_after,omitzero"`
}

